{
  "name": "opencode-go-quota",
  "version": "0.3.2",
  "description": "OpenCode Desktop titlebar ring and hover card for OpenCode Go allowance, with Console or API-key login.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-go",
    "quota",
    "usage"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/boingsetta/opencode-go-quota.git"
  },
  "homepage": "https://github.com/boingsetta/opencode-go-quota",
  "bugs": {
    "url": "https://github.com/boingsetta/opencode-go-quota/issues"
  },
  "exports": {
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "dist",
    "docs",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "vite build",
    "watch": "vite build --watch",
    "typecheck": "tsc --noEmit",
    "check": "npm run typecheck && npm run build"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  },
  "devDependencies": {
    "@opencode/client": "^2.2.0",
    "solid-js": "^1.9.0",
    "typescript": "^5.9.0",
    "vite": "^7.0.0",
    "vite-plugin-solid": "^2.11.0"
  }
}
